<?php
require __DIR__.'/../../config/bootstrap.php';
use Pharmacy\Auth\Authorization;use Pharmacy\Support\Csrf;use Pharmacy\Audit\AuditLogger;
Authorization::requireRole('ADMIN');$message=$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{Csrf::validate((string)($_POST['csrf']??''));$allowed=['estate_name','near_expiry_days_1','near_expiry_days_2','near_expiry_days_3','session_timeout_minutes'];$up=$pdo->prepare('INSERT INTO system_settings(setting_key,setting_value,updated_by) VALUES(:key,:value,:user) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach($allowed as $key){$value=trim((string)($_POST[$key]??''));if($key!=='estate_name'&&(!ctype_digit($value)||(int)$value<1))throw new DomainException('Numeric settings must be positive integers.');$up->execute(['key'=>$key,'value'=>$value,'user'=>(int)$_SESSION['user']['id']]);}(new AuditLogger($pdo))->log((int)$_SESSION['user']['id'],'UPDATE','SETTINGS','system_settings',null,null,array_intersect_key($_POST,array_flip($allowed)),$_SERVER['REMOTE_ADDR']??null);$message='Settings saved.';}catch(Throwable $e){$error=$e->getMessage();}}
$settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM system_settings')->fetchAll() as $s)$settings[$s['setting_key']]=$s['setting_value'];$title='Settings';require __DIR__.'/../../templates/header.php';?>
<h2 class="page-title">System Settings</h2><?php if($message):?><div data-flash="<?=htmlspecialchars($message)?>"></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="card"><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=htmlspecialchars(Csrf::token())?>"><div class="col-md-6"><label class="form-label">Estate / Operating Company Name</label><input class="form-control" name="estate_name" value="<?=htmlspecialchars($settings['estate_name']??'Estate Pharmacy')?>" required></div><div class="col-md-3"><label class="form-label">Session Timeout (minutes)</label><input class="form-control" type="number" min="1" name="session_timeout_minutes" value="<?=htmlspecialchars($settings['session_timeout_minutes']??'30')?>"></div><div class="w-100"></div><?php foreach(['near_expiry_days_1'=>'Expiry Alert 1 (days)','near_expiry_days_2'=>'Expiry Alert 2 (days)','near_expiry_days_3'=>'Expiry Alert 3 (days)'] as $k=>$l):?><div class="col-md-3"><label class="form-label"><?=$l?></label><input class="form-control" type="number" min="1" name="<?=$k?>" value="<?=htmlspecialchars($settings[$k]??($k==='near_expiry_days_1'?'30':($k==='near_expiry_days_2'?'60':'90')))?>"></div><?php endforeach;?><div class="col-12"><button class="btn btn-dark">Save Settings</button></div></form></div></div><?php require __DIR__.'/../../templates/footer.php';
